here = Path(__file__).parent / "subs"
here.mkdir(exist_ok=True)
for lang, lines in L.items():
    assert len(lines) == 45, (lang, len(lines))
    old = {f"s{i + 1:02}": t for i, t in enumerate(lines)}
    seg = {}
    for k, t in old.items():
        seg[k] = t
        for n in ORDER_EXTRA:
            if n.split("t")[0] == k:
                seg[n] = EXTRA[lang][n]
    (here / f"{lang}.json").write_text(json.dumps({"lang": lang, "segments": seg}, ensure_ascii=False, indent=1), encoding="utf-8")
print("subs written:", ", ".join(L))
